'use server';

import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  // Validate input
  if (!title || !content) {
    return { success: false, error: 'Title and content are required' };
  }

  try {
    // TODO: Add your actual database/API call here to create the post
    // Example: await db.posts.create({ title, content });

    // Invalidate the "posts" cache tag
    // This ensures that the next request will fetch fresh data
    // and NOT serve stale cached content
    revalidateTag('posts');

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to create post'
    };
  }
}

